class Heap{constructor(){this.a=[];}push(x){let a=this.a,i=a.length;a.push(x);while(i){let p=(i-1)>>1;if(a[p].cost<=x.cost)break;a[i]=a[p];i=p;}a[i]=x;}pop(){const a=this.a,r=a[0],x=a.pop();if(a.length){let i=0;while(i*2+1<a.length){let j=i*2+1;if(j+1<a.length&&a[j+1].cost<a[j].cost)j++;if(a[j].cost>=x.cost)break;a[i]=a[j];i=j;}a[i]=x;}return r;}get length(){return this.a.length;}}
const forbidden=new Set(['motorway','motorway_link','construction','proposed','raceway','busway']);
