export function energy(minutes,mass=70,met=4){return {gross:met*3.5*mass/200*minutes,active:Math.max(met-1,0)*3.5*mass/200*minutes};}
export function fare(seconds,profile='single',newPass=false){const p=POLICY.profiles[profile];if(!p)throw new Error('INVALID_PROFILE');if(!Number.isFinite(seconds)||seconds<0)throw new Error('INVALID_DURATION');const minutes=seconds===0?0:Math.ceil(seconds/60-1e-12),unlock=minutes?p.unlock:0,ride=minutes*p.rate,pass=newPass&&profile==='day'&&minutes?p.pass:0;return {minutes,unlock,ride,pass,total:unlock+ride+pass,currency:'USD',tax:'not_included',cap_applied:false,policy:POLICY.id,warnings:seconds>p.threshold*60?['LONG_RIDE_RULE_UNVERIFIED']:[]};}
export function stationUsable(s,role,now=Date.now()/1000){return s.status_present!==false&&!s.status_error&&s.installed&&s[role==='start'?'renting':'returning']&&Number.isFinite(s.timestamp)&&now-s.timestamp<=300&&s.timestamp-now<60&&(role==='start'?s.ebikes>0:s.docks>0);}
